window.PCP_SEARCH = [{"n":"Round RCP","g":"Reinforced Concrete Pipe Round (RCP)","c":"Pipe Culverts","f":"products-pipe.html","h":"round rcp reinforced concrete pipe round (rcp) pipe culverts available in diameters of 12–144 inches in 8 ft lengths. standard pipe is manufactured to astm c76 wall b class iii; class iv and v available upon request. compressive strengths range from 4,000 to 8,000 psi.","s":""},{"n":"Headwalls","g":"Reinforced Concrete Pipe Round (RCP)","c":"Pipe Culverts","f":"products-pipe.html","h":"headwalls reinforced concrete pipe round (rcp) pipe culverts precast concrete headwalls provide a cost-effective and durable solution for terminating reinforced concrete pipe while reducing erosion, improving site aesthetics, and simplifying installation. designed for storm drainage systems, headwalls are available to accommodate a wide range of pipe sizes and project requirements.","s":""},{"n":"Safety Ends","g":"Reinforced Concrete Pipe Round (RCP)","c":"Pipe Culverts","f":"products-pipe.html","h":"safety ends reinforced concrete pipe round (rcp) pipe culverts precast concrete safety ends deliver a cost-effective solution for terminating drainage pipe while improving safety, reducing erosion, and creating a finished appearance. ideal for roadway, municipal, and commercial stormwater systems, safety ends install quickly and require minimal field labor.","s":""},{"n":"Flared End Sections","g":"Reinforced Concrete Pipe Round (RCP)","c":"Pipe Culverts","f":"products-pipe.html","h":"flared end sections reinforced concrete pipe round (rcp) pipe culverts precast concrete flared ends are engineered to enhance drainage system performance by improving water flow and reducing erosion around pipe openings. factory-produced for consistency and durability, flared ends deliver a clean finished appearance and efficient installation for roadway, municipal, and commercial projects.","s":""},{"n":"Bends, Tees & Wyes","g":"Reinforced Concrete Pipe Round (RCP)","c":"Pipe Culverts","f":"products-pipe.html","h":"bends, tees & wyes reinforced concrete pipe round (rcp) pipe culverts precast bends, wyes & tees eliminate the need for costly field-fabricated connections while providing a durable, engineered solution for directional changes and pipe intersections. designed to integrate seamlessly with reinforced concrete pipe systems, these fittings support faster installation and long-term performance in demanding infrastructure applications.","s":""},{"n":"RCPA Pipe","g":"Reinforced Concrete Pipe Arch (RCPA)","c":"Pipe Culverts","f":"products-pipe.html?grp=1","h":"rcpa pipe reinforced concrete pipe arch (rcpa) pipe culverts equivalent round diameters of 15–72 inches, manufactured per astm c506, class ii, iii and iv.","s":""},{"n":"Headwalls","g":"Reinforced Concrete Pipe Arch (RCPA)","c":"Pipe Culverts","f":"products-pipe.html?grp=1","h":"headwalls reinforced concrete pipe arch (rcpa) pipe culverts precast concrete headwalls provide a cost-effective and durable solution for terminating reinforced concrete pipe while reducing erosion, improving site aesthetics, and simplifying installation. designed for storm drainage systems, headwalls are available to accommodate a wide range of pipe sizes and project requirements.","s":""},{"n":"Safety Ends","g":"Reinforced Concrete Pipe Arch (RCPA)","c":"Pipe Culverts","f":"products-pipe.html?grp=1","h":"safety ends reinforced concrete pipe arch (rcpa) pipe culverts precast concrete safety ends deliver a cost-effective solution for terminating drainage pipe while improving safety, reducing erosion, and creating a finished appearance. ideal for roadway, municipal, and commercial stormwater systems, safety ends install quickly and require minimal field labor.","s":""},{"n":"Flared End Sections","g":"Reinforced Concrete Pipe Arch (RCPA)","c":"Pipe Culverts","f":"products-pipe.html?grp=1","h":"flared end sections reinforced concrete pipe arch (rcpa) pipe culverts precast concrete flared ends are engineered to enhance drainage system performance by improving water flow and reducing erosion around pipe openings. factory-produced for consistency and durability, flared ends deliver a clean finished appearance and efficient installation for roadway, municipal, and commercial projects.","s":""},{"n":"Bends, Tees & Wyes","g":"Reinforced Concrete Pipe Arch (RCPA)","c":"Pipe Culverts","f":"products-pipe.html?grp=1","h":"bends, tees & wyes reinforced concrete pipe arch (rcpa) pipe culverts precast bends, wyes & tees eliminate the need for costly field-fabricated connections while providing a durable, engineered solution for directional changes and pipe intersections. designed to integrate seamlessly with reinforced concrete pipe systems, these fittings support faster installation and long-term performance in demanding infrastructure applications.","s":""},{"n":"Headwalls","g":"Box Culvert Accessories","c":"Box Culverts","f":"products-box.html?grp=3","h":"headwalls box culvert accessories box culverts precast headwalls terminate the culvert run, retain the embankment and help prevent erosion at the inlet and outlet.","s":""},{"n":"Safety Ends","g":"Box Culvert Accessories","c":"Box Culverts","f":"products-box.html?grp=3","h":"safety ends box culvert accessories box culverts precast safety ends terminate the culvert at the embankment slope, providing a traversable end treatment for roadside safety.","s":""},{"n":"Bends & Fittings","g":"Box Culvert Accessories","c":"Box Culverts","f":"products-box.html?grp=3","h":"bends & fittings box culvert accessories box culverts precast bends and fittings change alignment and connect box runs without field-fabricated connections.","s":""},{"n":"Catch Basins","g":"Precast Drainage Structures","c":"Drainage & Site Solutions","f":"products-drainage.html","h":"catch basins precast drainage structures drainage & site solutions collect stormwater runoff and trap sediment and debris before it enters the storm drain system.","s":""},{"n":"Manholes","g":"Precast Drainage Structures","c":"Drainage & Site Solutions","f":"products-drainage.html","h":"manholes precast drainage structures drainage & site solutions provide access for inspection and maintenance and serve as junctions where storm drain lines connect or change direction.","s":""},{"n":"Outlet Control Structures","g":"Precast Drainage Structures","c":"Drainage & Site Solutions","f":"products-drainage.html","h":"outlet control structures precast drainage structures drainage & site solutions control the rate at which stormwater leaves detention and retention ponds.","s":""},{"n":"Weir Inlets","g":"Precast Drainage Structures","c":"Drainage & Site Solutions","f":"products-drainage.html","h":"weir inlets precast drainage structures drainage & site solutions inlets with a weir opening that controls how stormwater enters the drainage system.","s":""},{"n":"Highway Trench Drains","g":"Trench Drain Systems","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=1","h":"highway trench drains trench drain systems drainage & site solutions trench drains built for highway traffic loads, collecting runoff along road surfaces.","s":""},{"n":"Airport Trench Drains","g":"Trench Drain Systems","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=1","h":"airport trench drains trench drain systems drainage & site solutions trench drains for airport aprons, taxiways and other paved airfield areas.","s":""},{"n":"Custom Drainage Solutions","g":"Trench Drain Systems","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=1","h":"custom drainage solutions trench drain systems drainage & site solutions drainage structures fabricated to project-specific dimensions and requirements.","s":""},{"n":"Jersey Barriers","g":"Traffic & Site Solutions","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=2","h":"jersey barriers traffic & site solutions drainage & site solutions precast concrete barriers that separate traffic lanes and protect work zones.","s":""},{"n":"V-Block Barriers","g":"Traffic & Site Solutions","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=2","h":"v-block barriers traffic & site solutions drainage & site solutions v-block barriers for site perimeters, traffic control and temporary separation.","s":""},{"n":"Parking Bumpers","g":"Traffic & Site Solutions","c":"Drainage & Site Solutions","f":"products-drainage.html?grp=2","h":"parking bumpers traffic & site solutions drainage & site solutions precast wheel stops that define parking spaces and protect curbs, walkways and structures.","s":""},{"n":"Full-Depth Deck Panels","g":"Bridge Deck Panels","c":"Precast Bridges","f":"products-bridges.html","h":"full-depth deck panels bridge deck panels precast bridges short-span bridges often utilize longitudinal, full-depth deck panels that are joined to form the complete bridge width and span length. these bridges may be surfaced with asphalt; however, many designs do not require an asphalt overlay. in many cases, the bridge railing is cast integrally with the exterior panel. alternatively, depending on the contractor's preference, the railing may be cast on-site.","s":""},{"n":"Partial-Depth Deck Panels","g":"Bridge Deck Panels","c":"Precast Bridges","f":"products-bridges.html","h":"partial-depth deck panels bridge deck panels precast bridges partial-depth deck panels consist of precast concrete segments supported by girders. these panels not only reduce the amount of cast-in-place concrete required but also serve as stay-in-place forms for the cast-in-place deck topping. many contractors prefer partial-depth deck panels because they improve worker safety and provide economical construction.","s":""},{"n":"Intermediate Bent Caps","g":"Bent Caps","c":"Precast Bridges","f":"products-bridges.html?grp=1","h":"intermediate bent caps bent caps precast bridges intermediate bent caps are precast and delivered directly to the construction site. extra-long caps may be fabricated in segments to facilitate transportation and lifting. these segments are joined in the field through closure pours after erection on their supporting structures.","s":""},{"n":"Abutment Caps","g":"Bent Caps","c":"Precast Bridges","f":"products-bridges.html?grp=1","h":"abutment caps bent caps precast bridges abutment caps, with or without wingwalls, can be precast and delivered directly to the construction site, reducing field forming at the bridge ends.","s":""},{"n":"Approach Slabs","g":"Approach Slabs","c":"Precast Bridges","f":"products-bridges.html?grp=2","h":"approach slabs approach slabs precast bridges bridge approach slabs can be fabricated as precast segments like precast deck spans and in accordance with ladotd standards.","s":""},{"n":"Wharves","g":"Structural Components","c":"Precast Bridges","f":"products-bridges.html?grp=3","h":"wharves structural components precast bridges many wharves and elevated dock structures share design and detailing characteristics with bridge structures. owners and designers frequently specify precast concrete components such as deck panels and caps, including heavily reinforced members designed to support industrial loading conditions. premier concrete is equipped and ready to meet the needs of the marine and industrial sectors through the manufacture of high-quality precast concrete products.","s":""},{"n":"Movable Concrete Barriers","g":"Structural Components","c":"Precast Bridges","f":"products-bridges.html?grp=3","h":"movable concrete barriers structural components precast bridges premier concrete maintains a substantial inventory of precast concrete barriers, enabling prompt delivery to meet customer needs and project schedules.","s":""},{"n":"Shoreblock® BD | Open Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreblock® bd | open cell shoretec® acb systems erosion control the most advanced, flexible, permeable and versatile system in the erosion control industry. blocks are threaded with polyester cable in both directions and manufactured with tapered sides and a notch and key interlocking system, giving outstanding performance under the most demanding hydraulic loading conditions — including channel bends and curves. mats are available in 8′ width and lengths up to 40′. one block style makes up the complete system, and it can be installed on virtually any slope angle.","s":""},{"n":"Shoreblock® BD | Closed Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreblock® bd | closed cell shoretec® acb systems erosion control the most advanced, flexible, permeable and versatile system in the erosion control industry. blocks are threaded with polyester cable in both directions and manufactured with tapered sides and a notch and key interlocking system, giving outstanding performance under the most demanding hydraulic loading conditions — including channel bends and curves. mats are available in 8′ width and lengths up to 40′. one block style makes up the complete system, and it can be installed on virtually any slope angle.","s":""},{"n":"Shoreblock® SD | Open Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreblock® sd | open cell shoretec® acb systems erosion control a flexible, interlocking matrix of concrete blocks of uniform size, shape and weight connected by a series of cables which pass longitudinally through preformed ducts in each block. shoreblock® sd combines the porosity, flexibility and vegetation encouragement of lightweight blankets with the non-erodible, self-weight and high tractive force resistance of a rigid lining. mats are available in 8′ width and lengths up to 40′, and can be joined to achieve greater lengths. cables are sized to provide a 5 to 1 cable strength to mat weight ratio; open cells comprise about 20% of the mat area.","s":""},{"n":"Shoreblock® SD | Closed Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreblock® sd | closed cell shoretec® acb systems erosion control a flexible, interlocking matrix of concrete blocks of uniform size, shape and weight connected by a series of cables which pass longitudinally through preformed ducts in each block. shoreblock® sd combines the porosity, flexibility and vegetation encouragement of lightweight blankets with the non-erodible, self-weight and high tractive force resistance of a rigid lining. mats are available in 8′ width and lengths up to 40′, and can be joined to achieve greater lengths. cables are sized to provide a 5 to 1 cable strength to mat weight ratio. closed cell blocks provide a solid surface for maximum armoring.","s":""},{"n":"Shoreloc® HP | Open Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreloc® hp | open cell shoretec® acb systems erosion control shoreloc® hand-placed block series, tested by colorado state university in accordance with the fhwa hydraulic performance testing protocol. a hand-placed option for sites where access is difficult or where the installation is an irregular shape.","s":""},{"n":"Shoreloc® HP | Closed Cell","g":"Shoretec® ACB Systems","c":"Erosion Control","f":"products-erosion.html","h":"shoreloc® hp | closed cell shoretec® acb systems erosion control shoreloc® hand-placed block series, tested by colorado state university in accordance with the fhwa hydraulic performance testing protocol. a hand-placed option for sites where access is difficult or where the installation is an irregular shape.","s":""},{"n":"ShoreFlex®","g":"ShoreFlex®","c":"Erosion Control","f":"products-erosion.html?grp=1","h":"shoreflex® shoreflex® erosion control the standard shoreflex® mat, with a black polypropylene geogrid and a single gs-50 backing.","s":""},{"n":"ShoreFlex® Ultra UV","g":"ShoreFlex®","c":"Erosion Control","f":"products-erosion.html?grp=1","h":"shoreflex® ultra uv shoreflex® erosion control a txdot-approved version with a tan, uv-resistant polypropylene geogrid for long-term sun exposure, on a single gs-50 backing.","s":""},{"n":"ShoreFlex® Pro","g":"ShoreFlex®","c":"Erosion Control","f":"products-erosion.html?grp=1","h":"shoreflex® pro shoreflex® erosion control the black polypropylene geogrid mat with a dual gs-50 and dns-50 backing for added seed and soil retention.","s":""},{"n":"ShoreFlex® Ultra UV Pro","g":"ShoreFlex®","c":"Erosion Control","f":"products-erosion.html?grp=1","h":"shoreflex® ultra uv pro shoreflex® erosion control the uv-resistant tan geogrid combined with the dual gs-50 and dns-50 backing.","s":""},{"n":"SJ-24","g":"ShoreJax™","c":"Erosion Control","f":"products-erosion.html?grp=2","h":"sj-24 shorejax™ erosion control capable of withstanding water velocities of up to 24 ft/s. manufactured by the dry cast process.","s":""},{"n":"SJ-48","g":"ShoreJax™","c":"Erosion Control","f":"products-erosion.html?grp=2","h":"sj-48 shorejax™ erosion control manufactured either dry cast or wet cast. reinforcing steel can be designed for each application and included in wet cast units.","s":""},{"n":"SJ-72","g":"ShoreJax™","c":"Erosion Control","f":"products-erosion.html?grp=2","h":"sj-72 shorejax™ erosion control larger unit, manufactured wet cast or dry cast. reinforcing steel can be designed for each application and included in wet cast units.","s":""},{"n":"BaseLok® GeoCell Layer","g":"EPEC System™","c":"Erosion Control","f":"products-erosion.html?grp=3","h":"baselok® geocell layer epec system™ erosion control a cellular confinement layer placed on the ground surface: a matrix of open cells with rigid walls designed to be filled with aggregate or sand. its 3d load transfer platform in the stone drainage layer improves system performance and resistance against hydraulic jump.","s":""},{"n":"Shoreblock® ACB Layer","g":"EPEC System™","c":"Erosion Control","f":"products-erosion.html?grp=3","h":"shoreblock® acb layer epec system™ erosion control mounted on top of the cellular confinement layer: a mat of blocks connected by cables.","s":""},{"n":"Optional Geosynthetic Layers","g":"EPEC System™","c":"Erosion Control","f":"products-erosion.html?grp=3","h":"optional geosynthetic layers epec system™ erosion control if desired, these may be mounted under the cellular confinement layer on top of the ground surface, as well as between the block layer and cellular confinement layer.","s":""},{"n":"4.5″ OS Mat","g":"OS Mats","c":"Pipeline","f":"products-pipeline.html","h":"4.5″ os mat os mats pipeline 8′ × 20′ mat of 12″ × 12″ blocks. mat weight 6,200 lbs in air, 3,500 lbs submerged.","s":""},{"n":"9″ OS Mat","g":"OS Mats","c":"Pipeline","f":"products-pipeline.html","h":"9″ os mat os mats pipeline 8′ × 20′ mat of 12″ × 12″ blocks. mat weight 10,500 lbs in air, 6,000 lbs submerged.","s":""},{"n":"12″ OS Mat","g":"OS Mats","c":"Pipeline","f":"products-pipeline.html","h":"12″ os mat os mats pipeline 8′ × 20′ mat of 12″ × 12″ blocks. mat weight 13,125 lbs in air, 7,500 lbs submerged.","s":""},{"n":"SB1010 Standard — Orange","g":"Sand Bags","c":"Pipeline","f":"products-pipeline.html?grp=2","h":"sb1010 standard — orange sand bags pipeline 14″ × 26″ woven polypropylene bag with 35–40 lbs of fill sand. 2,000 hour uv rating, uv stabilized thread and a tight weave to minimize sifting. 60 bags per pallet 20 pallets per truckload 1,200 bags per truckload","s":"60 bags per pallet | 20 pallets per truckload | 1,200 bags per truckload"},{"n":"SB101 Standard — White","g":"Sand Bags","c":"Pipeline","f":"products-pipeline.html?grp=2","h":"sb101 standard — white sand bags pipeline 14″ × 26″ woven polypropylene bag, 40 lbs of sand. 2,000 hour uv rating with heavy duty tie cord for closing.","s":""},{"n":"SB1010HD Heavy Duty — Orange","g":"Sand Bags","c":"Pipeline","f":"products-pipeline.html?grp=2","h":"sb1010hd heavy duty — orange sand bags pipeline 14″ × 26″ heavy duty woven polypropylene bag, 40 lbs of sand. 4,000 hour uv rating — the longest lasting option.","s":""},{"n":"3:1 Sand-Cement Bag — 60 lb","g":"3:1 Bags","c":"Pipeline","f":"products-pipeline.html?grp=3","h":"3:1 sand-cement bag — 60 lb 3:1 bags pipeline 4000 psi sand-cement mix in a biodegradable jute burlap bag. available in 60 lb. burlap bags.","s":""},{"n":"1-5/8 × 8 × 16 Solid","g":"Mobile Home Block","c":"Masonry","f":"products-masonry.html?grp=5","h":"1-5/8 × 8 × 16 solid mobile home block masonry thin solid block used for fine height adjustments at the top of a pier. lets installers bring each pier to the exact level needed before shimming to the frame.","s":""},{"n":"2-1/4 × 8 × 16 Solid","g":"Mobile Home Block","c":"Masonry","f":"products-masonry.html?grp=5","h":"2-1/4 × 8 × 16 solid mobile home block masonry solid leveling block for mid-range height adjustments on mobile home piers. combine with other solid units to reach the precise pier height without cutting block.","s":""},{"n":"4 × 8 × 16 Solid","g":"Mobile Home Block","c":"Masonry","f":"products-masonry.html?grp=5","h":"4 × 8 × 16 solid mobile home block masonry solid cap block set on top of hollow pier block to spread the load from the home’s frame evenly across the pier. also used as a leveling course and for general solid masonry work.","s":""},{"n":"16 × 4 × 16 Full Pad","g":"Mobile Home Block","c":"Masonry","f":"products-masonry.html?grp=5","h":"16 × 4 × 16 full pad mobile home block masonry solid concrete footing pad placed on prepared ground at the base of each pier. its wide footprint spreads the home’s weight across the soil to reduce settling.","s":""},{"n":"8 × 8 × 16 Regular","g":"Mobile Home Block","c":"Masonry","f":"products-masonry.html?grp=5","h":"8 × 8 × 16 regular mobile home block masonry hollow-core concrete block stacked to build pier height, set with the cells vertical for maximum strength. the standard building unit for mobile home piers.","s":""},{"n":"8 × 8 × 8","g":"Foundation Block","c":"Masonry","f":"products-masonry.html?grp=6","h":"8 × 8 × 8 foundation block masonry half-length foundation block for corners, pier ends and finishing courses. pairs with 8 × 8 × 16 block to complete walls and piers without cutting.","s":""},{"n":"8 × 8 × 16","g":"Foundation Block","c":"Masonry","f":"products-masonry.html?grp=6","h":"8 × 8 × 16 foundation block masonry full-size foundation block for stem walls, crawl space walls, piers and house leveling. the standard unit for most residential foundation and repair work.","s":""},{"n":"6 × 8 × 16","g":"Foundation Block","c":"Masonry","f":"products-masonry.html?grp=6","h":"6 × 8 × 16 foundation block masonry narrower foundation block for underpinning, short walls and lighter-load applications where an 8″ wall is not required.","s":""},{"n":"Utility Brick 2 × 4 × 8","g":"Foundation Block","c":"Masonry","f":"products-masonry.html?grp=6","h":"utility brick 2 × 4 × 8 foundation block masonry solid concrete brick for shimming, filling gaps and small repairs around foundations, steps and piers.","s":""},{"n":"Jumbo Brick 4 × 4 × 8","g":"Foundation Block","c":"Masonry","f":"products-masonry.html?grp=6","h":"jumbo brick 4 × 4 × 8 foundation block masonry larger solid concrete brick for building up piers, steps and small walls with fewer units than standard brick.","s":""},{"n":"Premier 6” Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"premier 6” wall walls hardscapes premier 6” wall features an innovative 6-inch profile designed for residential and light commercial jobs up to 8’. this wall is one of the most innovative srw products the industry has seen in 30 years. its unique and patented .75 sq. ft. block design is changing the industry. only weighing 44 lbs. per unit, it reduces installer fatigue. premier 6” wall also beats all other wall systems for strength, performance, freight efficiencies and ease of construction.","s":""},{"n":"Premier 8” Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"premier 8” wall walls hardscapes premier 8” wall is the high-performance block preferred by architects, builders, developers and engineers nationwide. it is known for its ease of installation, strength, and versatility. it provides extra support for the most critical applications. whether the wall is supporting a retail development or backyard sanctuary, it is the best solution for any type of retaining wall application.","s":""},{"n":"Mandeville Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"mandeville wall walls hardscapes the modern, smooth texture of this block adds a sleek and contemporary look to any design. not only can it be used for walls, but it can also function as a cap, providing versatility in its use. with the ability to create columns and build freeform walls, this product offers endless possibilities for design and construction. the options are truly limitless with this versatile and modern stacking block.","s":""},{"n":"Mandeville Tumble Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"mandeville tumble wall walls hardscapes this block has a charming nostalgic appearance and texture, giving any product a rustic and weathered look. not only can it be used for walls, but also caps, adding versatility to its functionality. the design options are endless as it can be used to create columns and freeform walls, making it a go-to product for any outdoor project.","s":""},{"n":"Tallulah Garden Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"tallulah garden wall walls hardscapes this wall is designed to be versatile and time-saving solution for curved wall applications. its trapezoidal shape eliminates the need for tedious cuts making installation quicker and easier. with its sleek and smooth finish, this wall adds a clean and modern touch to any landscaping project.","s":""},{"n":"Tallulah Tumble Garden Wall","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"tallulah tumble garden wall walls hardscapes this wall is designed to be versatile and time-saving solution for curved wall applications. its trapezoidal shape eliminates the need for tedious cuts making installation quicker and easier. with its tumbled and rustic finish, this wall adds nostalgic charm to any landscaping project.","s":""},{"n":"Universal Cap","g":"Walls","c":"Hardscapes","f":"products-hardscapes.html","h":"universal cap walls hardscapes whether you are finishing a large-scale construction project or a diy home renovation, our split face universal cap is the perfect finishing touch. its unique trapezoidal shape allows for easy use on both curved and straight walls. this is a highly versatile cap for most residential and commercial projects.","s":""},{"n":"Pavers","g":"Pavers","c":"Hardscapes","f":"products-hardscapes.html?grp=1","h":"pavers pavers hardscapes ","s":""},{"n":"Circle Fire Pit | Staggered Style","g":"Fire Pits","c":"Hardscapes","f":"products-hardscapes.html?grp=2","h":"circle fire pit | staggered style fire pits hardscapes 45-piece fire pit kit built from tallulah tumble wall units in cypress brown blend.","s":""},{"n":"Circle Fire Pit | Stacked Style","g":"Fire Pits","c":"Hardscapes","f":"products-hardscapes.html?grp=2","h":"circle fire pit | stacked style fire pits hardscapes 42-piece fire pit kit built from tallulah tumble wall units in parish grey blend.","s":""},{"n":"Square Fire Pit | Mandeville Tumble Wall","g":"Fire Pits","c":"Hardscapes","f":"products-hardscapes.html?grp=2","h":"square fire pit | mandeville tumble wall fire pits hardscapes 36-piece fire pit kit built from mandeville tumble wall units in cypress brown blend.","s":""},{"n":"Square Fire Pit | Mandeville Wall","g":"Fire Pits","c":"Hardscapes","f":"products-hardscapes.html?grp=2","h":"square fire pit | mandeville wall fire pits hardscapes 36-piece fire pit kit built from mandeville wall units in parish grey blend.","s":""}];
